package postgres

// The placeholder is generated by the query builder; the caller identity is
// always bound as a value. Apply this before ranking and LIMIT, including raw
// vector SQL and the MATERIALIZED BM25 path that bypass GORM row hooks.
func privateSourceCandidatePredicate(placeholder string) string {
	return `NOT EXISTS (SELECT 1 FROM feishu_private_kbs private_kb
 WHERE private_kb.kb_id=embeddings.knowledge_base_id AND private_kb.owner_id <> ` + placeholder + `)`
}
